const body = $json.body || $json;
const question = String(body.question || body.khach_hoi || '').trim();
const source_q_id = body.source_q_id || `Q-${Date.now()}`;
const channel = body.channel || 'webhook_demo';
const products_override = body.products || null;
const faq_override = body.faq || null;

function normalize(text) {
  return String(text || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'd')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const nq = normalize(question);
const riskPatterns = [
  ['prompt_injection', /ignore previous|system prompt|developer message|bo qua huong dan|tiet lo prompt|huong dan cu/],
  ['outside_retail_scope', /ve may bay|dat ve|chuyen tien|tai khoan cua khach khac|mat khau cua khach khac|mat khau/]
];
const risk_flags = riskPatterns.filter(([, re]) => re.test(nq)).map(([flag]) => flag);

function routeIntent(text) {
  if (/ve may bay|dat ve|chuyen tien|system prompt|developer message|mat khau cua khach khac|mat khau|he thong/.test(text)) return { scope: 'out_of_scope', intent: 'ngoai_pham_vi' };
  if (/hoan tien|refund|tra tien/.test(text)) return { scope: 'retail_support', intent: 'hoan_tien' };
  if (/khieu nai|tuc gian|\bthai do\b/.test(text)) return { scope: 'retail_support', intent: 'khieu_nai' };
  if (/cho mua|cho minh mua|cho dat|cho order|mua ngay|dat mua|dat hang|chot don|\border\b|them vao gio|mua 1|lay 1|lay mot|mua mot|mua sp|ban cho|cho 1|toi muon mua|tui muon mua|mua cai|mua chie|mua em/.test(text)) return { scope: 'retail_support', intent: 'dat_mua' };
  if (/bao hanh|roi vo|\bloi\b|\bhong\b|dien tu|ky thuat/.test(text)) return { scope: 'retail_support', intent: 'ky_thuat' };
  if (/shop co san pham nao|catalog|danh sach san pham|danh sach|danh muc|xin danh sach|cho xin|ton kho|con hang|het hang|airbeat|binh giu nhiet|minikey|blendgo|\bp01\b|\bp02\b|\bp03\b|\bp04\b|ban nhung san pham nao|con hang khong|\btai nghe\b|\bbinh nuoc\b|\bban phim\b|\bmay xay\b/.test(text)) return { scope: 'retail_support', intent: 'san_pham' };
  if (/\bgia\b|\bphi\b|\bvat\b|hoa don|freeship|bao nhieu tien|thanh toan|\bcod\b/.test(text)) return { scope: 'retail_support', intent: 'gia' };
  if (/don|giao|ship|trang thai|lien he|zalo|hotline|doi|mau|size|hoi|cua hang|shop|goi qua|giang sinh|dich vu|ho tro/.test(text)) return { scope: 'retail_support', intent: 'thong_tin' };
  return { scope: 'out_of_scope', intent: 'ngoai_pham_vi' };
}

const routed = routeIntent(nq);
const is_risk = risk_flags.length > 0 || routed.scope === 'out_of_scope';

return [{
  json: {
    source_q_id,
    channel,
    question,
    normalized_question: nq,
    is_risk,
    risk_flags,
    scope: routed.scope,
    intent: routed.intent,
    products_override,
    faq_override
  }
}];

const item = $json;
return [{
  json: {
    source_q_id: item.source_q_id,
    channel: item.channel,
    question: item.question,
    scope: 'out_of_scope',
    intent: 'ngoai_pham_vi',
    route: 'refuse_or_ticket',
    cache_hit: false,
    cache_score: 0,
    risk_flags: item.risk_flags || [],
    answer: 'Mình chỉ hỗ trợ các câu hỏi về sản phẩm, đặt mua, đơn hàng, giao nhận, thanh toán, đổi trả, bảo hành và khiếu nại của cửa hàng.',
    nguon: 'khong_co',
    need_llm: false,
    need_human: false,
    ticket: null
  }
}];

const item = $json;

function vnd(value) {
  return `${Number(value).toLocaleString('vi-VN')} VNĐ`;
}

if (item.intent === 'san_pham') {
  if (item.bestProduct) {
    const p = item.bestProduct;
    const stockText = p.stock > 0 ? `Còn ${p.stock} sản phẩm` : 'Tạm hết hàng';
    return [{ json: {
      source_q_id: item.source_q_id, channel: item.channel, question: item.question,
      scope: item.scope, intent: 'san_pham', route: 'product_catalog',
      cache_hit: true, cache_score: item.cache_score,
      answer: `${p.name} (${p.id}) hiện có giá ${vnd(p.price)}. ${stockText}. ${p.summary} Bảo hành ${p.warranty_months} tháng. ${p.promo}`,
      nguon: `CATALOG-${p.id}`,
      product: p,
      need_llm: false, need_human: false,
      confidence: 0.94,
      ticket: null
    }}];
  }
  return [{ json: {
    source_q_id: item.source_q_id, channel: item.channel, question: item.question,
    scope: item.scope, intent: 'san_pham', route: 'product_catalog',
    cache_hit: true, cache_score: 1,
    answer: `Cửa hàng đang có:\n${item.products.map(p => `- ${p.id}: ${p.name} - ${vnd(p.price)} (${p.stock > 0 ? 'còn hàng' : 'tạm hết hàng'})`).join('\n')}\nBạn muốn xem chi tiết hoặc đặt mua mã nào?`,
    nguon: 'CATALOG',
    products: item.products.map(({id, name, price, stock}) => ({id, name, price, stock})),
    need_llm: false, need_human: false,
    confidence: 0.92,
    ticket: null
  }}];
}

if (item.intent === 'dat_mua') {
  if (!item.bestProduct) {
    return [{ json: {
      source_q_id: item.source_q_id, channel: item.channel, question: item.question,
      scope: item.scope, intent: 'dat_mua', route: 'order_request',
      cache_hit: false, cache_score: 0,
      answer: `Bạn muốn đặt mua sản phẩm nào? Hiện trong vector DB có: ${item.products.map(p => `${p.id} ${p.name}`).join(', ')}.`,
      nguon: 'CATALOG', need_llm: false, need_human: true,
      confidence: 0.72,
      ticket: { ticket_id: `ORD-${item.source_q_id}`, nguoi_phu_trach: 'Tư vấn bán hàng', trang_thai: 'can_bo_sung_san_pham' }
    }}];
  }
  const p = item.bestProduct;
  const inStock = p.stock > 0;
  return [{ json: {
    source_q_id: item.source_q_id, channel: item.channel, question: item.question,
    scope: item.scope, intent: 'dat_mua', route: 'order_request',
    cache_hit: true, cache_score: item.cache_score,
    answer: inStock
      ? `Mình đã ghi nhận yêu cầu đặt mua ${p.name} (${p.id}) giá ${vnd(p.price)}. CSKH sẽ xác nhận số lượng, địa chỉ giao hàng và phương thức thanh toán với bạn.`
      : `${p.name} (${p.id}) hiện tạm hết hàng. Mình đã tạo yêu cầu để CSKH báo bạn khi hàng về hoặc tư vấn sản phẩm thay thế.`,
    nguon: `CATALOG-${p.id}`,
    product: p,
    need_llm: false, need_human: true,
    confidence: inStock ? 0.9 : 0.82,
    ticket: { ticket_id: `ORD-${item.source_q_id}`, nguoi_phu_trach: inStock ? 'Tư vấn bán hàng' : 'CSKH báo hàng', product_id: p.id, product_name: p.name, trang_thai: inStock ? 'cho_xac_nhan' : 'cho_hang_ve' }
  }}];
}

const best = item.bestFaq;
const sensitive = ['hoan_tien', 'khieu_nai'].includes(item.intent) || (best && ['hoan_tien', 'khieu_nai'].includes(best.intent));
const finalIntent = item.intent === 'thong_tin' && best && best.intent ? best.intent : item.intent;
const needHuman = sensitive;

return [{ json: {
  source_q_id: item.source_q_id, channel: item.channel, question: item.question,
  scope: item.scope, intent: finalIntent,
  route: needHuman ? 'human_ticket' : 'faq_cache',
  cache_hit: true, cache_score: item.cache_score,
  top3_faq_ids: item.top3_faq_ids,
  answer: best ? best.cau_tra_loi : 'Thông tin hỗ trợ khách hàng dịch vụ bán lẻ.',
  nguon: best ? best.id : 'F01',
  need_llm: false, need_human: needHuman,
  confidence: needHuman ? 0.82 : 0.93,
  reason: needHuman ? 'Có nguồn FAQ nhưng đây là case nhạy cảm cần CSKH cấp 2 xem xét.' : 'FAQ cache hit với nguồn rõ ràng.',
  ticket: needHuman ? { ticket_id: `T-${item.source_q_id}`, nguoi_phu_trach: 'Đội hoàn tiền / CSKH cấp 2' } : null
}}];

const item = $json || {};
const ragContext = item.rag_context || 'Không có RAG context phù hợp.';
const ragChunks = Array.isArray(item.rag_chunks) ? item.rag_chunks : [];
const sourceHints = [];
if (item.bestFaq && item.bestFaq.id) sourceHints.push(item.bestFaq.id);
if (item.bestProduct && item.bestProduct.id) sourceHints.push('CATALOG-' + item.bestProduct.id);
if (!sourceHints.length && Array.isArray(item.top3_faq_ids)) sourceHints.push(...item.top3_faq_ids);

function fallbackAnswer() {
  if (item.bestFaq) return 'Theo thông tin từ cửa hàng (' + (item.bestFaq.nguon || item.bestFaq.id || 'FAQ') + '): ' + item.bestFaq.cau_tra_loi;
  if (item.bestProduct) {
    const p = item.bestProduct;
    return p.name + ' (' + p.id + ') hiện có giá ' + Number(p.price || 0).toLocaleString('vi-VN') + ' VNĐ. ' + (p.stock > 0 ? 'Còn hàng (' + p.stock + ' SP).' : 'Tạm hết hàng.') + ' ' + (p.summary || '') + ' ' + (p.promo || '');
  }
  return 'Mình chưa có thông tin chính xác trong tài liệu cửa hàng (RAG context miss). CSKH sẽ kiểm tra và phản hồi bạn sớm.';
}

const prompt = `Bạn là trợ lý CSKH Retail Care. Chỉ trả lời dựa trên RAG CONTEXT bên dưới, không bịa thông tin ngoài nguồn.

Câu hỏi khách hàng: ${item.question || ''}

RAG CONTEXT:
${ragContext}

RAG CHUNKS JSON:
${JSON.stringify(ragChunks)}

Yêu cầu:
- Trả lời ngắn gọn, lịch sự bằng tiếng Việt.
- Nếu có nguồn, ghi nguồn ở cuối dạng [FAQ Fxx] hoặc [CATALOG-Pxx].
- Nếu RAG context không đủ, nói CSKH sẽ kiểm tra và phản hồi lại.`;

return [{
  json: {
    ...item,
    sourceHints,
    fallback_answer: fallbackAnswer(),
    gemini_request: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }]
    }
  }
}];

const original = ($items('3a. Build RAG Gemini Request')[0] || {}).json || {};
const response = $json.body || $json || {};
const text = (((response.candidates || [])[0] || {}).content || {}).parts?.map(p => p.text || '').join('').trim();
const errorText = response.error ? JSON.stringify(response.error).slice(0, 500) : null;

return [{
  json: {
    ...original,
    need_llm: true,
    route: 'llm_fallback',
    raw_llm_answer: text || original.fallback_answer || 'CSKH xin ghi nhận thông tin và phản hồi bạn sớm.',
    sources_used: original.sourceHints && original.sourceHints.length ? original.sourceHints : ['khong_co'],
    llm_provider: text ? 'google_gemini' : 'fallback_gemini_http_error',
    llm_model: 'gemini-flash-latest',
    llm_error: text ? null : (errorText || 'Gemini returned no text candidate'),
    rag_used: true
  }
}];

const item = $json || {};
const sensitiveIntent = ['hoan_tien', 'khieu_nai', 'ngoai_pham_vi', 'dat_mua'].includes(item.intent);
const sources = Array.isArray(item.sources_used) ? item.sources_used : [];
const sourceText = sources.length ? sources.join(', ') : 'khong_co';

const judgePrompt = `Bạn là LLM-as-Judge cho chatbot CSKH bán lẻ. Hãy chấm câu trả lời dựa trên RAG CONTEXT, nguồn và chính sách chuyển người thật.

INPUT JSON:
${JSON.stringify({
  question: item.question || '',
  answer: item.raw_llm_answer || item.answer || '',
  intent: item.intent || '',
  route: item.route || '',
  rag_context: item.rag_context || '',
  rag_chunks: item.rag_chunks || [],
  sources_used: sources,
  cache_score: item.cache_score || 0,
  sensitive_intent: sensitiveIntent
}, null, 2)}

RUBRIC:
- groundedness_score 0.0-1.0: câu trả lời có bám RAG context/nguồn không.
- answer_quality_score 0.0-1.0: câu trả lời có ngắn gọn, lịch sự, hữu ích không.
- confidence 0.0-1.0: độ tin cậy tổng hợp.
- need_human=true nếu thiếu nguồn RAG rõ, confidence < 0.70, groundedness_score < 0.70, hoặc intent nhạy cảm cần CSKH xử lý.
- Nếu RAG không có thông tin và câu trả lời nói sẽ chuyển CSKH thì groundedness không được cao, confidence nên thấp và need_human=true.

Trả về DUY NHẤT JSON hợp lệ, không markdown, schema:
{
  "groundedness_score": 0.0,
  "answer_quality_score": 0.0,
  "confidence": 0.0,
  "need_human": true,
  "verdict": "pass|review|fail",
  "reason": "một câu tiếng Việt ngắn",
  "evidence": ["nguồn hoặc đoạn RAG dùng để chấm"]
}`;

return [{
  json: {
    ...item,
    judge_request: {
      contents: [{ role: 'user', parts: [{ text: judgePrompt }] }],
      generationConfig: { responseMimeType: 'application/json' }
    },
    judge_source_text: sourceText,
    judge_sensitive_intent: sensitiveIntent
  }
}];

const original = ($items('4a. Build LLM Judge Request')[0] || {}).json || {};
const response = $json.body || $json || {};
const rawText = (((response.candidates || [])[0] || {}).content || {}).parts?.map(p => p.text || '').join('').trim();
const errorText = response.error ? JSON.stringify(response.error).slice(0, 500) : null;

function clamp01(value, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(0, Math.min(1, n));
}

function heuristicFallback() {
  const sources = original.sources_used || [];
  const hasValidSource = sources.length > 0 && !sources.includes('khong_co');
  const sensitive = Boolean(original.judge_sensitive_intent);
  if (sensitive) {
    return {
      groundedness_score: hasValidSource ? 0.75 : 0.45,
      answer_quality_score: 0.75,
      confidence: 0.65,
      need_human: true,
      verdict: 'review',
      reason: 'Fallback judge: intent nhạy cảm cần CSKH xử lý.',
      evidence: sources
    };
  }
  if (!hasValidSource || (original.cache_score || 0) < 0.2) {
    return {
      groundedness_score: 0.45,
      answer_quality_score: 0.7,
      confidence: 0.45,
      need_human: true,
      verdict: 'review',
      reason: 'Fallback judge: nguồn RAG chưa đủ rõ.',
      evidence: sources
    };
  }
  return {
    groundedness_score: 0.85,
    answer_quality_score: 0.85,
    confidence: 0.85,
    need_human: false,
    verdict: 'pass',
    reason: 'Fallback judge: câu trả lời có nguồn RAG rõ.',
    evidence: sources
  };
}

let parsed = null;
let parseError = null;
if (rawText) {
  try {
    parsed = JSON.parse(rawText.replace(/^```json\s*/i, '').replace(/```$/i, '').trim());
  } catch (err) {
    parseError = String(err && err.message ? err.message : err).slice(0, 300);
  }
}
const judge = parsed || heuristicFallback();
const confidence = clamp01(judge.confidence, 0.45);
const groundedness = clamp01(judge.groundedness_score, confidence);
const quality = clamp01(judge.answer_quality_score, confidence);
const needHuman = Boolean(judge.need_human) || confidence < 0.7 || groundedness < 0.7;

return [{
  json: {
    ...original,
    confidence,
    need_human: needHuman,
    reason: judge.reason || (needHuman ? 'LLM judge yêu cầu CSKH kiểm tra.' : 'LLM judge xác nhận câu trả lời bám nguồn.'),
    judge_provider: rawText && parsed ? 'google_gemini' : 'fallback_judge_parser',
    judge_model: 'gemini-flash-latest',
    judge_error: rawText && parsed ? null : (errorText || parseError || 'Gemini judge returned no parseable JSON'),
    judge_raw: rawText || null,
    judge_score: {
      groundedness_score: groundedness,
      answer_quality_score: quality,
      confidence,
      verdict: judge.verdict || (needHuman ? 'review' : 'pass'),
      evidence: Array.isArray(judge.evidence) ? judge.evidence : []
    }
  }
}];
